If $P_W(W=0) = P_W(W=1) = 1/2$, then $p_Y(y) = p_Y(-y)$, because 
    \begin{equation} p_Y(y) = \frac{1}{2}(p_{Y|W}(y \mid 0) + p_{Y|W}(y \mid 1)) \overset{\eqref{eqn:output-symmetric-channel}}{=} \frac{1}{2}(p_{Y|W}(-y \mid 1) + p_{Y|W}(-y \mid 0)) = p_Y(-y). 
    \end{equation}

If the LLR of $y$ calculated by \eqref{eq:def_ell} is $\ell$, then the LLR corresponding to $-y$ is $-\ell$, because
    \begin{equation} \ell = \log\frac{p_{Y|W}(y \mid 0)}{p_{Y|W}(y \mid 1)} \Rightarrow \log\frac{p_{Y|W}(-y \mid 0)}{p_{Y|W}(-y \mid 1)} = \log\frac{p_{Y|W}(y \mid 1)}{p_{Y|W}(y \mid 0)} = -\log\frac{p_{Y|W}(y \mid 0)}{p_{Y|W}(y \mid 1)} = -\ell. 
    \end{equation}

This lemma follows from Bayes' rule and the definition of $L$ in \eqref{eq:def_ell}. First, consider the case where $\theta(y) = 0$. We have $\Pr(\theta(Y) \neq W \mid Y = y) = \Pr(W = 1 \mid Y = y)$ and 
    \begin{eqnarray}
        \Pr(W = 1 \mid Y = y) &=& \frac{\Pr(Y = y \mid W = 1) \Pr(W = 1)}{\Pr(Y = y \mid W = 0) \Pr(W = 0) + \Pr(Y = y \mid W = 1) \Pr(W = 1)}\\
        &\overset{(a)}{ = }& \frac{q_1(y)}{q_0(y) + q_1(y)}  \overset{(b)}{ = } \frac{1}{1 + \exp(|\ell|)},
    \end{eqnarray}
    where (a) follows from the assumption that $W$ is uniform, and (b) holds because $\theta(y) = 0$ implies $\ell \geq 0$. Similarly, for the case where $\theta(y) = 1$, we also have
    \begin{eqnarray}
        \Pr(W = 0 \mid Y = y) = \frac{1}{1 + \exp(|\ell|)}.
    \end{eqnarray}

When $\underline{W} = [{W}_1, {W}_2, \ldots, {W}_N]$ are i.i.d., given $\underline{Y} = \underline{y}$, the guessing posterior $P_{\underline{W}|\underline{Y}}(\theta(\underline{y})\oplus \underline{e} \mid \underline{y})$ is given by:
    \begin{equation} P_{\underline{W}|\underline{Y}}(\theta(\underline{y})\oplus \underline{e} \mid \underline{y}) =  \prod_{i:e_i = 1}\frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_i = 0}\frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}.
    \end{equation}

Using the i.i.d. property of $\underline{W}$ and the 
    memoryless property of the channel, Bayes' rule gives
    \begin{eqnarray}
        P_{\underline{W}|\underline{Y}}\left(\theta(\underline{y}) \oplus \underline{e} \mid \underline{y}\right) = \prod_{i = 1}^N P_{{W}|Y} \left(\theta(y_i) \oplus e_i \mid y_i\right).
    \end{eqnarray}
Inspecting this product, the factors with $e_i = 1$ correspond to flipped hard decisions and, by Lemma~\ref{lem:y-neq-w-cond-ell}, contribute $\prod_{i:e_i = 1} \frac{1}{1+\exp(|\ell_i|)}$. The factors with $e_i = 0$ correspond to unchanged hard decisions and contribute $\prod_{i:e_i = 0} \frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}$. Multiplying these two parts together leads to \eqref{eq:posterior}.

For a given codebook $\mathcal{C}$, given $\underline{Y} = \underline{y}$, the guessing posterior $P_{\underline{{W}}|\underline{Y}}(\theta(\underline{y})\oplus \underline{e} \mid \underline{y})$ is given by:
    \begin{equation} P_{\underline{W}|\underline{Y}}\left(\theta(\underline{y})\oplus \underline{e} \mid \underline{y}\right) = \left\{\begin{array}{ll}
        C(\underline{y})\prod_{i:e_i = 1}\frac{1}{1+\exp(|\ell_i|)}\prod_{i:e_i = 0}\frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}      & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. ,
\end{equation}
where $C(\underline{y})$ is a normalization coefficient given by $C(\underline{y}) = 2^{N - K} \cdot  \prod_{i = 1}^N p_Y(y_i)/p_{\underline{Y}}(\underline{y})$.

P_{\underline{W}|\underline{Y}}\left(\theta(\underline{y})\oplus \underline{e} \mid \underline{y}\right) = \left\{\begin{array}{ll}
        C(\underline{y})\prod_{i:e_i = 1}\frac{1}{1+\exp(|\ell_i|)}\prod_{i:e_i = 0}\frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}      & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. ,

We deduce via the following steps:
    \begin{align}
    P_{\underline{W}|\underline{Y}}\left(\theta(\underline{y})\oplus \underline{e} \mid \underline{y}\right) = & \frac{P_{\underline{W}}(\theta(\underline{y})\oplus \underline{e}) p_{\underline{Y}|\underline{W}}\left(\underline{y} \mid \theta(\underline{y})\oplus \underline{e}\right)}{ p_{\underline{Y}}(\underline{y})} \\
    = &  \left\{\begin{array}{ll}
        C'(\underline{y})\cdot p_{\underline{Y}|\underline{W}}\left(\underline{y} \mid \theta(\underline{y})\oplus \underline{e}\right)   & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. \\
    = & \left\{\begin{array}{ll}
        C'(\underline{y})\cdot \prod_{i=1}^{N} p_{Y|W}\left(y_i \mid \theta(y_i)\oplus e_i\right)   & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. \\
    = & \left\{\begin{array}{ll}
        C(\underline{y})\cdot \prod_{i=1}^{N} P_{W|Y}\left(\theta(y_i)\oplus e_i \mid y_i\right)   & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. \\
    = & \left\{\begin{array}{ll}
        C(\underline{y})\cdot \prod_{i:e_i = 1}\frac{1}{1+\exp(|\ell_i|)}\prod_{i:e_i = 0}\frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}.   & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. , \end{align}
where:
\begin{itemize}
    \item \eqref{eqn:posterior_C_1} is Bayes' rule;
    \item \eqref{eqn:posterior_C_2} holds, because if $\theta(\underline{y})\oplus \underline{e} \in \mathcal{C}$ then $P_{\underline{W}}(\theta(\underline{y})\oplus \underline{e}) = 2^{-K}$ (codeword drawn uniformly at random from $\mathcal{C}$), and otherwise $P_{\underline{W}}(\theta(\underline{y})\oplus \underline{e}) = 0$, with
    \begin{eqnarray}
        C'(\underline{y}) = \frac{P_{\underline{W}}(\theta(\underline{y})\oplus \underline{e})}{p_{\underline{Y}}(\underline{y})} = \frac{1}{2^K p_{\underline{Y}}(\underline{y})};
    \end{eqnarray}
    \item \eqref{eqn:posterior_C_3} follows from the memoryless property of the channel;
    \item \eqref{eqn:posterior_C_4} is Bayes' rule, with
    \begin{eqnarray} C(\underline{y}) = C'(\underline{y}) \frac{\prod_{i = 1}^N p_Y(y_i)}{\prod_{i = 1}^N P_W(\theta(y_i) \oplus e_i)} = 2^{N - K} \frac{\prod_{i = 1}^N p_Y(y_i)}{p_{\underline{Y}}(\underline{y})},
    \end{eqnarray}
    where we note that each $W_i$ has the same marginal probability, i.e., uniform over $\mathbb{F}_2$, and consequently that each $Y_i$   
    has the same marginal probability density distribution, i.e., $p_Y(y) = (q_0(y) + q_1(y))/2$.
    \item \eqref{eqn:posterior_C_5} follows from the same argument as that in the proof of Lemma~\ref{lemma:posterior_probability}.
\end{itemize}

P_{\underline{W}|\underline{Y}}\left(\theta(\underline{y})\oplus \underline{e} \mid \underline{y}\right) = & \frac{P_{\underline{W}}(\theta(\underline{y})\oplus \underline{e}) p_{\underline{Y}|\underline{W}}\left(\underline{y} \mid \theta(\underline{y})\oplus \underline{e}\right)}{ p_{\underline{Y}}(\underline{y})} \\
    = &  \left\{\begin{array}{ll}
        C'(\underline{y})\cdot p_{\underline{Y}|\underline{W}}\left(\underline{y} \mid \theta(\underline{y})\oplus \underline{e}\right)   & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. \\
    = & \left\{\begin{array}{ll}
        C'(\underline{y})\cdot \prod_{i=1}^{N} p_{Y|W}\left(y_i \mid \theta(y_i)\oplus e_i\right)   & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. \\
    = & \left\{\begin{array}{ll}
        C(\underline{y})\cdot \prod_{i=1}^{N} P_{W|Y}\left(\theta(y_i)\oplus e_i \mid y_i\right)   & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. \\
    = & \left\{\begin{array}{ll}
        C(\underline{y})\cdot \prod_{i:e_i = 1}\frac{1}{1+\exp(|\ell_i|)}\prod_{i:e_i = 0}\frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}.   & \text{if } \theta(\underline{y})\oplus \underline{e} \in \mathcal{C} \\
        0     & \text{else}
        \end{array} \right. ,

When the channel is output-symmetric in the sense of \eqref{eqn:output-symmetric-channel}, for any codebook $\mathcal{C}$, the AGP is given by:
    \begin{eqnarray} \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \underline{e} \mid \underline{Y})\right] = \int_{\mathbb{R}^N}\prod_{i=1}^{N}p_{Y}(y_i) \left(\prod_{i:e_i = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_i = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right)\mathrm{d}\underline{y}.
    \end{eqnarray}

Considering an arbitrary codebook $\mathcal{C}$, we have
    \begin{eqnarray} \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \underline{e} \mid \underline{Y})\right] = \int_{\mathbb{R}^N} p_{\underline{Y}}(\underline{y}) P_{\underline{W}|\underline{Y}}(\theta(\underline{y})\oplus \underline{e} \mid \underline{y})
        \mathrm{d}\underline{y}.
    \end{eqnarray}
    Applying Lemma~\ref{lemma:posterior_probability_codebook} and plugging into the expression \eqref{eqn:C-y} of $C(\underline{y})$, we obtain
    \begin{eqnarray}
        && \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \underline{e} \mid \underline{Y})\right]\\
        &=& \int_{\mathbb{R}^N} 2^{N - K} \prod_{i=1}^{N}p_{Y}(y_i) \left(\prod_{i:e_i = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_i = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right) \mathbf{1}\left(\theta(\underline{y}) \oplus \underline{e} \in \mathcal{C}\right) \mathrm{d}\underline{y}. \end{eqnarray}
    Under the output-symmetric condition \eqref{eqn:output-symmetric-channel} and its associated properties \eqref{eqn:prop_symm_1} and \eqref{eqn:prop_symm_2}, we have $p_Y(y) = p_Y(-y)$ for any $y \in \mathbb{R}$, and the values $y$ and $-y$ result in the same $|\ell|$. Consider any $\underline{y} \in \mathbb{R}_{+}^{N}$ (i.e., the first quadrant in $\mathbb{R}^N$). There are $2^N$ ways of flipping the signs of the $N$ elements of $\underline{y}$ to yield $2^N$ points in $\mathbb{R}^N$ (including $\underline{y}$ itself), and all these points lead to the same value of $\prod_{i=1}^{N}p_{Y}(y_i) \left(\prod_{i:e_i = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_i = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right)$ in the integral in \eqref{eqn:agp-all}. Furthermore, exactly $2^K$ among all these $2^N$ points lead to $\mathbf{1}\left(\theta(\underline{y}) \oplus \underline{e} \in \mathcal{C}\right) = 1$ since there are exactly $2^K$ different codewords in the codebook $\mathcal{C}$. Consequently, we can evaluate the integral \eqref{eqn:agp-all} as
    \begin{eqnarray}
        && \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \underline{e} \mid \underline{Y})\right]\\
        &=& 2^K 2^{N - K} \int_{\mathbb{R}_{+}^{N}} \prod_{i=1}^{N}p_{Y}(y_i) \left(\prod_{i:e_i = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_i = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right) \mathrm{d}\underline{y}\\
        &=& \int_{\mathbb{R}^{N}} \prod_{i=1}^{N}p_{Y}(y_i) \left(\prod_{i:e_i = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_i = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right) \mathrm{d}\underline{y},
    \end{eqnarray}
    where in the last step we have restored the integral over $\mathbb{R}^N$ by noticing that the integrands in all the $2^N$ quadrants are identical according to the output-symmetric condition.

A codeword tester sequentially tests whether $\theta(\underline{y}) \oplus \underline{e}(t) \in \mathcal{C}$ for $t=1,\ldots,T$. It is clear that there are two possibilities:
\begin{itemize}
    \item There exists at least one index within $\{1, 2, \ldots, T\}$ such that the corresponding EP passes the test of codeword tester, and we denote the smallest such index as $\hat{t}$ and declare the decoded codeword to be $\hat{\underline{w}} = \theta(\underline{y}) \oplus \underline{e}(\hat{t})$;
    \item There is no index within $\{1, 2, \ldots, T\}$ such that the corresponding EP passes the test of codeword tester, and we declare a decoding failure with $\hat{\underline{w}} = \emptyset$.

We show that MLD and the thus described GRAND algorithm lead to the same decoded codeword: 
\begin{align}
    \hat{\underline{w}} & = \arg\max_{\underline{w}\in \mathcal{C}}\left\{p_{\underline{Y}|\underline{W}}(\underline{y} \mid \underline{w})\right\} = \arg\max_{\underline{w}\in \mathcal{C}}\left\{\frac{p_{\underline{Y}}(\underline{y})P_{\underline{W}|\underline{Y}}(\underline{w} \mid \underline{y})}{P_{\underline{W}}(\underline{w})}\right\} \\

    & = \theta(\underline{y}) \oplus \arg\max_{\underline{e}\in \mathbb{F}_2^N}\left\{P_{\underline{W}|\underline{Y}}(\theta(\underline{y})\oplus \underline{e} \mid \underline{y})\mathbf{1}(\theta(\underline{y})\oplus \underline{e}\in \mathcal{C})\right\} \\
    & = \theta(\underline{y}) \oplus \arg\max_{\underline{e}\in \mathbb{F}_2^N}\left\{\prod_{i:e_i = 1}\frac{1}{1+\exp(|\ell_i|)}\prod_{i:e_i = 0}\frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}\mathbf{1}(\theta(\underline{y})\oplus \underline{e}\in \mathcal{C})\}\right\} \\
    & = \theta(\underline{y}) \oplus \arg\max_{\underline{e}:\theta(\underline{y})\oplus \underline{e}\in \mathcal{C}}\left\{\exp\left(\sum_{i:e_i = 0}|\ell_i|\right)\right\} \\
    & = \theta(\underline{y}) \oplus \arg\min_{\underline{e}:\theta(\underline{y})\oplus \underline{e}\in \mathcal{C}}\left\{\sum_{i:e_i=1} |\ell_i|\right\} = \theta(\underline{y}) \oplus \arg\min_{\underline{e}:\theta(\underline{y})\oplus \underline{e}\in \mathcal{C}} \left\{\zeta(\underline{e})\right\}. \end{align}
Here,
\begin{itemize}
    \item \eqref{eq:ml_23} rewrites the MLD criterion, noting that $P_{\underline{W}}$ is uniform over $\mathcal{C}$ and that $p_{\underline{Y}}(\underline{y})$ does not depend on the choice of $\underline{w}$;
    \item \eqref{eq:ml_3} is from \eqref{eq:posterior_2} in Lemma~\ref{lemma:posterior_probability_codebook}, again noting that the leading normalization coefficient $C(\underline{y})$ therein can be removed.
\end{itemize}
The rule described in \eqref{eq:ml_4} is that we identify the EP as the one, among all those leading to some codeword in $\mathcal{C}$, that attains the smallest soft weight. When we execute the GRAND algorithm with an EP generator that outputs monotonically non-decreasing soft weights, the procedure exactly solves \eqref{eq:ml_4}. This completes our proof.

For convenience, we denote
\begin{equation}
\pi_{\underline{y}}(\mathcal{E})
=
\{\pi_{\underline{y}}(\underline{e}(1)),\ldots,\pi_{\underline{y}}(\underline{e}(T))\}.
\end{equation}

In an ORB-type GRAND algorithm, the $t$-th tested EP is denoted by $\pi(\underline{e}(t))$, and hence the corresponding AGP is given by
\begin{equation} p_t := \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) \mid \underline{Y})\right].
\end{equation}

Consider an output-symmetric channel satisfying \eqref{eqn:output-symmetric-channel} and a permutation rule $\pi_{\underline y}$ that depends on $\underline y$ only through the reliability values $|\ell_1|,\ldots,|\ell_N|$. Then for any codebook $\mathcal C$, we have
    \begin{equation} \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}) \mid \underline{Y})\right] = \int_{\mathbb{R}^N}\prod_{i=1}^{N}p_{Y}(y_i) \left(\prod_{i:\pi_{\underline{y}}(\underline{e})_i = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:\pi_{\underline{y}}(\underline{e})_i = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right)\mathrm{d}\underline{y},
    \end{equation}



    In particular, for the rank-based permutation, we have:
    \begin{align} p_t = N!\int_{\underline{y}:|\ell_{1}|<|\ell_{2}|<\cdots<|\ell_{N}|}\prod_{i=1}^{N}p_{Y}(y_i)\left(\prod_{i:e_i(t) = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_i(t) = 0} \frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}\right)\mathrm{d}\underline{y}.
    \end{align}

For an arbitrary codebook $\mathcal{C}$, following the steps in \eqref{eq:agp_expect2int} and \eqref{eqn:agp-all}, we have 
    \begin{align}
        & \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}) \mid \underline{Y})\right] = \int_{\mathbb{R}^N} p_{\underline{Y}}(\underline{y}) P_{\underline{W}|\underline{Y}}(\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}) \mid \underline{y})
        \mathrm{d}\underline{y}.  \\
        = &\int_{\mathbb{R}^N} 2^{N - K} \prod_{i=1}^{N}p_{Y}(y_i) \left(\prod_{i:\pi_{\underline{y}}(\underline{e})_i = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:\pi_{\underline{y}}(\underline{e})_i = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right) \mathbf{1}\left(\theta(\underline{y}) \oplus \pi_{\underline{y}}(\underline{e}) \in \mathcal{C}\right) \mathrm{d}\underline{y}. 
    \end{align}
    Then, similar to the derivation in Proposition~\ref{prop:agp}, we have:
    \begin{eqnarray} \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}) \mid \underline{Y})\right] = \int_{\mathbb{R}^N}\prod_{i=1}^{N}p_{Y}(y_i)\left(\prod_{i:\pi_{\underline{y}}(\underline{e})_i = 1 } \frac{1}{1+\exp(|\ell_i|)} \prod_{i:\pi_{\underline{y}}(\underline{e})_i = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right)\mathrm{d}\underline{y}
    \end{eqnarray}
    For the rank-based permutation $\pi$, we further have:
    \begin{align}
        & \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) \mid \underline{Y})\right] = \int_{\mathbb{R}^N}\prod_{i=1}^{N}p_{Y}(y_{i})\left(\prod_{i:e_{r_i} = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_{r_i} = 0} \frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}\right)\mathrm{d}\underline{y}. \\
        = & N!\int_{\underline{y}:|\ell_{1}|<|\ell_{2}|<\cdots<|\ell_{N}|}\prod_{i=1}^{N}(p_{Y}(y_i))\left(\prod_{i:e_i(t) = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_i(t) = 0} \frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}\right)\mathrm{d}\underline{y}. \end{align}

    To obtain the second equality in \eqref{eq:Long4.3} from \eqref{eq:Long4.2}, we use the symmetry of the integrand under coordinate permutations. Since the channel is memoryless, the density factorizes as $\prod_{i=1}^{N}p_Y(y_i)$, and the remaining product terms depend on $\underline{y}$ only through the multiset $\{|\ell_1|,\ldots,|\ell_N|\}$. Hence, permuting the coordinates of $\underline{y}$ leaves the integrand unchanged. Let $\mathcal{A}$ denote the order-statistics region $\mathcal{A}=\{\underline{y}:|\ell_1|<|\ell_2|<\cdots<|\ell_N|\}$. Assuming a continuous output distribution (so ties occur with probability zero), $\mathbb{R}^N$ can be partitioned into $N!$ disjoint regions obtained by permuting the inequalities in $\mathcal{A}$, and the integral over each region is identical. Therefore, the integral over $\mathbb{R}^N$ equals $N!$ times the integral over $\mathcal{A}$. Moreover, on $\mathcal{A}$ the ranking is $\underline{r}=(1,2,\ldots,N)$, i.e., $r_i=i$, so that $e_{r_i}(t)=e_i(t)$, which yields \eqref{eq:Long4.3}.

\textit{Scheme~2: empirical target-EP ordering.}
    We repeatedly draw a transmitted codeword $\underline{W}$ and generate the corresponding channel output $\underline{Y}$ according to the channel. For each realization, we record the target EP before applying the rank-based permutation,
    \begin{equation}
        \underline{E}_{\mathrm{tar}}
        =
        \pi_{\underline{Y}}^{-1}\!\left(\theta(\underline{Y})\oplus \underline{W}\right).
    \end{equation}
    Conditioned on $\underline{Y}$, the event $\underline{E}_{\mathrm{tar}}=\underline{e}$ is equivalent to $\underline{W}=\theta(\underline{Y})\oplus\pi(\underline{e})$. Hence, by averaging over $\underline{Y}$, the empirical frequency of each unpermuted EP estimates its AGP:
    \begin{equation}
        \Pr(\underline{E}_{\mathrm{tar}}=\underline{e})
        =
        \mathbf{E}_{\underline{Y}}\!\left[
        P_{\underline{W}|\underline{Y}}\!\left(
        \theta(\underline{Y})\oplus \pi(\underline{e})\mid \underline{Y}
        \right)\right].
    \end{equation}
    This scheme avoids evaluating a closed-form expression for $p_t$ and may be useful when such an expression is difficult to obtain.

\underline{E}_{\mathrm{tar}}
        =
        \pi_{\underline{Y}}^{-1}\!\left(\theta(\underline{Y})\oplus \underline{W}\right).

\caption{Finite-list construction of $\widetilde{\mathcal{E}}$ for RS-ORBGRAND} \begin{algorithmic}[1]
        \REQUIRE Initial ordered EP list $\mathcal{E}=\{\underline{e}(t)\}_{t=1}^{T_1}$; maximum number of tests $T<T_1$; permutation criterion $\pi_{\underline{Y}}$.
        \ENSURE Reshuffled EP list $\widetilde{\mathcal{E}}$.
        \FOR{$t = 1$ to $T_1$}
            \STATE Compute the AGP:
            \begin{equation}
                p_t \leftarrow \mathbf{E}_{\underline{Y}}\!\left[
                P_{\underline{W}|\underline{Y}}\!\left(
                \theta(\underline{Y}) \oplus \pi(\underline{e}(t)) \mid \underline{Y}
                \right)\right].
            \end{equation}
        \ENDFOR
        \STATE Sort $\{p_t\}_{t=1}^{T_1}$ in descending order to obtain $\widetilde{\pi}$.
        \STATE Reshuffle $\mathcal{E}$ according to $\widetilde{\pi}$ and keep the first $T$ EPs to form $\widetilde{\mathcal{E}}$.
        \STATE Use \textbf{Algorithm~\ref{alg:ORBTYPE}} with $(\widetilde{\mathcal{E}},\, \pi_{\underline{Y}})$ for decoding.
    \end{algorithmic}

The target-miss probability is given by
    \begin{align}
        P_{\text{I}} = \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t))\neq \underline{W}(1),\forall\ t \leq T) = 1 - \sum_{t=1}^{T} p_t, \end{align}
    where $p_t = \mathbf{E}_{\underline{Y}}\left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) \mid \underline{Y})\right]$.

For a given ORB-type GRAND algorithm, the quantities $\{p_t\}_{t=1}^T$ describe the probability distribution of the position of the target EP in the ordered sequence $\{\pi(\underline{e}(t))\}$, i.e.,
\begin{equation}
p_t
=
\Pr(\theta(\underline{Y})\oplus\pi(\underline{e}(t))=\underline{W}(1)).
\end{equation}

From Proposition~\ref{prop:search_problem}, we have
\begin{equation}
    \Pr(\theta(\underline{Y})\oplus\pi(\underline{e}(i))\neq
    \underline{W}(1),\,\forall\, i \le t) = 1-\sum_{i=1}^{t}p_i .
\end{equation}
Therefore,
\begin{align}
    & \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) = \underline{W}(1)) \\
    = & \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(i))\neq \underline{W}(1),\forall\ i \leq t-1) - \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(i))\neq \underline{W}(1),\forall\ i \leq t)\\
    = & \left(1 - \sum_{i=1}^{t-1}p_i\right) - \left(1 - \sum_{i=1}^{t}p_i\right) = p_t,
\end{align}

P_{\text{II}}
    = & \sum_{t=1}^{T}\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) = \underline{W}(1))\cdot\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathbfcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1))\\
    = & \sum_{t=1}^{T}p_{t}\cdot\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathbfcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)),

For notational convenience, we introduce the pre-target codeword-hit probability:
\begin{equation}
    f(\mathbfcal{C},\mathcal{E},t) := \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathbfcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)), \end{equation}
which is the conditional probability that although the $t$-th test would identify the sent codeword, at least one earlier EP during the first $t-1$ tests leads to a competing codeword.

We have
    \begin{align}
        f(\mathbfcal{C},\mathcal{E},t) &= \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathbfcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1))\\
        &= 1 - \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1))\\
        &= 1 - \frac{\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\ t'< t, \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1))}{\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1))}\\
        &= 1 - \frac{1}{p_{t}} \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\ t'< t, \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)), \end{align}
    where the last equality is from Corollary~\ref{coro:distribution_pt}.

    We then manipulate the joint probability in \eqref{eqn:pre-target-hit-prob-joint} accordingly:
    \begin{align}
        & \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\ t'< t, \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \notag\\
        &= \Pr(\{\underline{W}(2),\underline{W}(3),\ldots,\underline{W}(2^K)\}\cap\{\theta(\underline{Y})\oplus \pi(\underline{e}(1)),\ldots,\theta(\underline{Y})\oplus \pi(\underline{e}(t - 1))\} = \emptyset, \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1))\notag\\
        &= \sum_{\underline{w} \in \mathbb{F}_2^N} \int_{\mathbb{R}^N} \mathrm{d}\underline{y} p_{\underline{Y}}(\underline{y}) P_{\underline{W}(1)|\underline{Y}}(\underline{w} \mid \underline{y}) \mathbf{1}(\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t))=\underline{w}) \times\notag\\
        &\quad\quad\ \Pr(\{\underline{W}(2),\underline{W}(3),\ldots,\underline{W}(2^K)\}\cap\{\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(1)),\ldots,\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t - 1))\} = \emptyset \mid \underline{Y} = \underline{y}, \underline{W}(1) = \underline{w}). \end{align}
    Using the Markov chain $\{\underline{W}(2),\underline{W}(3),\ldots,\underline{W}(2^K)\} \leftrightarrow \underline{W}(1) \leftrightarrow \underline{Y}$, we have
    \begin{align}
        &\Pr(\{\underline{W}(2),\underline{W}(3),\ldots,\underline{W}(2^K)\}\cap\{\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(1)),\ldots,\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t - 1))\} = \emptyset \mid \underline{Y} = \underline{y}, \underline{W}(1) = \underline{w}) \notag\\
        &= \Pr(\{\underline{W}(2),\underline{W}(3),\ldots,\underline{W}(2^K)\}\cap\{\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(1)),\ldots,\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t - 1))\} = \emptyset \mid \underline{W}(1) = \underline{w}),
    \end{align}
    for which, we can follow the generation of $\mathbfcal{C}$ via sampling without replacement from $\mathbb{F}_2^N$ to obtain a closed-form expression as
    \begin{align}
        &\Pr(\{\underline{W}(2),\underline{W}(3),\ldots,\underline{W}(2^K)\}\cap\{\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(1)),\ldots,\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t - 1))\} = \emptyset \mid \underline{W}(1) = \underline{w}) \notag\\
        &= \prod_{m=2}^{2^K}\frac{2^N+2-t-m}{2^N+1-m}. \end{align}
    This can be explained as follows: to ensure $\underline{W}(2) \notin \{\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(1)),\ldots,\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t - 1))\}$ there are $(2^N - 1) - (t - 1) = 2^N - t$ choices among $2^N - 1$ possibilities (the condition $\underline{W}(1) = \underline{w}$ dictates that we can only sample $\underline{W}(2)$ from $2^N - 1$ possible vectors in $\mathbb{F}_2^N$), and continuing this, to ensure $\underline{W}(m) \notin \{\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(1)),\ldots,\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t - 1))\}$ there are $2^N - (m - 1) - (t - 1) = 2^N - t - m + 2$ choices among $2^N - (m - 1)$ possibilities, until $m = 2^K$. By canceling out common denominators and numerators in \eqref{eqn:P-emptyset-1}, we can further rewrite it as
    \begin{align}
        &\Pr(\{\underline{W}(2),\underline{W}(3),\ldots,\underline{W}(2^K)\}\cap\{\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(1)),\ldots,\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t - 1))\} = \emptyset  \mid  \underline{W}(1) = \underline{w}) \notag\\
        &= \prod_{t'=1}^{t-1}\frac{2^N-2^K+1-t'}{2^N-t'}. \end{align}
    Applying \eqref{eqn:P-emptyset-2} back to \eqref{eqn:emptyset-y-W1}, we obtain
    \begin{align}
        & \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\ t'< t, \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \notag\\
        &= \left(\prod_{t'=1}^{t-1}\frac{2^N-2^K+1-t'}{2^N-t'} \right) \sum_{\underline{w} \in \mathbb{F}_2^N} \int_{\mathbb{R}^N} \mathrm{d}\underline{y} p_{\underline{Y}}(\underline{y}) P_{\underline{W}(1)|\underline{Y}}(\underline{w} \mid \underline{y}) \mathbf{1}(\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t))=\underline{w}) \\
        &= \left(\prod_{t'=1}^{t-1}\frac{2^N-2^K+1-t'}{2^N-t'} \right) \int_{\mathbb{R}^N} \mathrm{d}\underline{y} p_{\underline{Y}}(\underline{y}) P_{\underline{W}(1)|\underline{Y}}(\theta(\underline{y})\oplus \pi_{\underline{y}}(\underline{e}(t)) \mid \underline{y}) \\
        &= \left(\prod_{t'=1}^{t-1}\frac{2^N-2^K+1-t'}{2^N-t'} \right) \mathbf{E}_{\underline{Y}}\left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) \mid \underline{Y})\right] \\
        &= \left(\prod_{t'=1}^{t-1}\frac{2^N-2^K+1-t'}{2^N-t'} \right) p_{t}.
    \end{align}
    Therefore, \eqref{eqn:pre-target-hit-prob-joint} is
    \begin{align}
        f(\mathbfcal{C},\mathcal{E},t) &= 1 - \frac{1}{p_{t}} \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\ t'< t, \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \\
        &= 1 - \frac{1}{p_{t}} \left(\prod_{t'=1}^{t-1}\frac{2^N-2^K+1-t'}{2^N-t'} \right) p_{t} \\
        &= 1 - \prod_{t'=1}^{t-1}\frac{2^N-2^K+1-t'}{2^N-t'},
    \end{align}
    completing the proof.

The target-preemption probability is given by:
    \begin{align}
        P_{\mathrm{II}} = \sum_{t=1}^{T} p_{t} \left(1 - \prod_{t' = 1}^{t-1} \frac{2^N-2^K+1-t'}{2^N-t'}\right). \end{align}

For a given ORB-type GRAND algorithm, over the random code ensemble, the probability that the codeword tester declares the decoded codeword after $t$ tests is given by:
     \begin{eqnarray}
         P_{\text{stop}}(t) &=& p_t (1 - f(t)) + \left(1-\sum_{i=1}^{t}p_i\right)(f(t+1)-f(t)), \quad\quad t = 1, \ldots, T - 1; \\
         P_{\text{stop}}(T) &=& \left(1-\sum_{i=1}^{T-1}p_i\right)(1-f(T)). \end{eqnarray}

For $t = 1, \ldots, T-1$, there are two situations under which the codeword tester stops after exactly $t$ tests: either the target EP is correctly identified at the $t$-th index in the ordered list and no earlier candidate produces a competing codeword, or the target EP is not among the first $t$ EPs in that list and the $t$-th test is the first pre-target codeword hit. So we have
     \begin{align}
        P_{\text{stop}}(t)& = p_t\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \notag \\
        &\quad\quad   +\sum_{i=t+1}^{2^N}\left( p_i  \left[\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(i)) =\underline{W}(1))\right.\right. \notag \\
        & \quad \quad \quad\quad \left.\left.- \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\ t'< t+1 \mid \theta(\underline{Y})\oplus \pi(\underline{e}(i))=\underline{W}(1))\right]\right) \\ 
        & = p_t(1 - f(t)) + \sum_{i=t+1}^{2^N}p_i[(1 - f(t)) - (1- f(t+1))], \\
        & = p_t(1 - f(t)) + \left(1 - \sum_{i=1}^{t}p_i\right)(f(t+1)-f(t)). \end{align}
    In \eqref{eq:6.1}, Corollary~\ref{coro:distribution_pt} is applied. The transition to \eqref{eq:6.2} follows from the exchangeability of the random code ensemble: conditioned on the target appearing at any index $i\ge t$, the probability that no competing codeword appears in the first $t-1$ tests depends only on the prefix length. Hence, for any $i\ge t$,
    \begin{equation}
    \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\, t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(i))=\underline{W}(1)) = 1-f(t),
    \end{equation}
    and similarly the corresponding probability with prefix length $t$ equals $1-f(t+1)$.

     The decoder may also stop only after the budget is reached: if the target has not been tested by the end of the first $T-1$ positions and there is no pre-target codeword hit in those tests, the tester stops after $T$ tests. So
     \begin{align}
        P_{\text{stop}}(T) & = \left(1 - \sum_{i=1}^{T-1} p_i \right) \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\notin \mathbfcal{C},\forall\, t'< T \mid \theta(\underline{Y})\oplus \pi(\underline{e}(j))=\underline{W}(1), j \geq T) \\
        &= \left(1 - \sum_{i=1}^{T-1} p_i \right)(1 - f(T)).
     \end{align}

Using the expressions of $P_{\text{stop}}(t)$ in Proposition~\ref{prop:stop_at_t}, we can obtain, after some algebraic manipulations:
    \begin{align}
        Q & = \sum_{t=1}^{T}t\, P_{\text{stop}}(t) \\





        & = T- \sum_{t=1}^{T} f(t) - \sum_{t=1}^{T-1}p_t\left(T -t - \sum_{i=t+1} ^{T}f(i)\right). \end{align}

Substituting $f(t) = 1 - \prod_{i=1}^{t-1}\frac{2^N-2^K+1-i}{2^N-i}$ given by Lemma~\ref{lemma:1} into \eqref{eq:length.5}, we have
    \begin{equation}
        Q = \sum_{t=1}^{T}\left(\prod_{i=1}^{t-1}\frac{2^N-2^K+1-i}{2^N-i}\right) - \sum_{t=1}^{T-1}p_t\left(\sum_{i=t+1}^{T}\prod_{j=1}^{i-1}\frac{2^N-2^K+1-j}{2^N-j}\right).
    \end{equation}

For a given ORB-type GRAND algorithm, conditioned on the event that the codeword tester stops after the $t$-th test, the probability that the declared codeword equals the transmitted codeword is
    \begin{align}
        P_{\text{succ}\mid\text{stop}}(t) &= \frac{p_t}{p_t + (1 - \sum_{i=1}^{t}p_i)\left( \frac{2^K-1}{2^N-t}\right)}, \quad\quad t = 1, \ldots, T - 1;\\
        P_{\text{succ}\mid\text{stop}}(T) &= \frac{p_T}{1 - \sum_{i=1}^{T-1}p_i}.
    \end{align}

From the proof of Proposition~\ref{prop:stop_at_t}, conditional on the event that the codeword tester stops after the $t$-th test, there are two mutually exclusive possibilities: the target EP is encountered at index~$t$ in the ordered list, and no earlier candidate produces a competing codeword, corresponding to correct decoding; or the target EP is not among the first $t$ EPs, and the $t$-th test is a pre-target codeword hit, corresponding to incorrect decoding. The probabilities of these two situations are respectively
    \begin{equation}
        \Pr(\text{correct at }t) = p_t(1-f(t)) \text{ and } \Pr(\text{incorrect at }t) =  \left(1 - \sum_{i=1}^{t}p_i\right)(f(t+1)-f(t)).
    \end{equation}
    Therefore, under the condition that the codeword tester stops after the $t$-th test, the probability of decoding correctly is:
    \begin{align}
        \frac{\Pr(\text{correct at }t)}{P_{\text{stop}}(t)} & = \frac{p_t(1-f(t))}{p_t(1-f(t)) + (1 - \sum_{i=1}^{t}p_i)(f(t+1)-f(t))} \\

        & = \frac{p_t}{p_t + (1 - \sum_{i=1}^{t}p_i)\left(1 - \frac{1 - f(t+1)}{1 - f(t)}\right)} = \frac{p_t}{p_t + (1 - \sum_{i=1}^{t}p_i)\left( \frac{2^K-1}{2^N-t}\right)},
    \end{align}
    for $t = 1, \ldots, T - 1$, and
    \begin{equation}
        \frac{\Pr(\text{correct at }T)}{P_{\text{stop}}(T)} = \frac{p_T(1-f(T))}{(1-\sum_{i=1}^{T-1}p_i)(1 - f(T))} = \frac{p_T}{1 - \sum_{i=1}^{T-1}p_i},
    \end{equation}
    for stopping after $T$ tests.

For ORB-type decoding applied to the random code ensemble, impose a maximum number of tests $T$ and consider the EP set available to the decoder. The decoding success probability $P_{\mathrm{succ}}$ is maximized by selecting the tested EPs so that their AGPs dominate those of the untested EPs and ordering the tested EPs in non-increasing AGP order, i.e.,
 \begin{equation}
     p_1\geq p_2\geq \cdots\geq p_T, \text{ and }\ p_i\geq p_j,\ \forall \ i\leq T<j.
 \end{equation}
This ordering also minimizes the average number of tests.

For the probability of decoding correctly, Theorem~\ref{th:random_error_rate} gives
     \begin{equation} P_{\text{succ}} = \sum_{t=1}^{T}p_t(1 - f(t)) = \sum_{t=1}^{T}p_t \left(\prod_{i=1}^{t-1}\frac{2^N-2^K+1-i}{2^N-i}\right),
     \end{equation}
     notice that $\left(\prod_{i=1}^{t-1}\frac{2^N-2^K+1-i}{2^N-i}\right)$ decreases monotonically with $t$. Therefore, in order to maximize $P_{\text{succ}}$, the tested EPs should be selected and ordered according to:
     \begin{equation} p_1\geq p_2\geq \cdots\geq p_T, \text{ and }\ p_i\geq p_j,\ \forall\ i\leq T<j.
     \end{equation}
     Meanwhile, Theorem~\ref{th:ave_guess_num} gives the average number of tests as
     \begin{equation}
         Q = T- \sum_{t=1}^{T} f(t) - \sum_{t=1}^{T-1}p_t\left(T -t - \sum_{i=t+1} ^{T}f(i)\right),
     \end{equation}
     notice that $\left(T -t - \sum_{i=t+1}^{T}f(i)\right)$ decreases monotonically with $t$ since any $f(i)$ is less than 1. Therefore, minimizing $Q$ is equivalent to assigning larger AGPs to larger coefficients, and the EPs should be selected and ordered according to:
     \begin{equation} p_1\geq p_2\geq \cdots\geq p_{T-1}, \text{ and }\ p_i\geq p_j,\ \forall\ i\leq T-1<j,
     \end{equation}
     which is slightly weaker than \eqref{eq:opti_condition_2}.

     Since \eqref{eq:opti_condition_2} implies the weaker condition \eqref{eq:opti_condition_3}, arranging the EPs according to non-increasing AGP simultaneously maximizes the decoding success probability and minimizes the average number of tests.

Consider a binary linear block code with rate $R=K/N$ and generator matrix 
$G\in\mathbb{F}_2^{K\times N}$. The corresponding codebook is
\begin{equation}
\mathcal{C}=\{G^T\underline{u}:\underline{u}\in\mathbb{F}_2^K\},
\end{equation}
which contains $2^K$ distinct codewords.

Based on the randomized indexing introduced in Section~\ref{SubSec:linear_channel_model} and the reasoning of Proposition~\ref{prop:error_division}, the total decoding error probability can be expressed as
    \begin{align}
        P_{\text{err}} & = \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t))\neq \underline{W}(1),\forall\ t\leq  T) \notag\\
        & \quad \quad + \sum_{t=1}^{T}\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) = \underline{W}(1)) \notag\\
        & \quad \quad \cdot\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathbfcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)). \end{align}
    The first term represents the event that the target EP $\theta(\underline{Y}) \oplus \underline{W}(1)$ is not contained in the tested EP set $\pi(\mathcal{E})$ (target-miss error), whereas the second term corresponds to the event that $\theta(\underline{Y}) \oplus \underline{W}(1)\in\pi(\mathcal{E})$ but at least another codeword in $\mathcal{C}$ also satisfies the verification condition before the target is reached (target-preemption error).

    For the target-miss error, the analysis follows the same reasoning as in Section~\ref{SubSec:random_error_rate}. Since its characterization depends only on the ordering of tested EPs and the channel statistics, Proposition~\ref{prop:search_problem}, Corollary~\ref{coro:distribution_pt}, and Proposition~\ref{prop:agp_pi} remain applicable to fixed linear block codes.


    We next consider the target-preemption error. Since $\mathbfcal{C}$ is only a randomized indexing of the fixed codebook $\mathcal{C}$, the codeword-membership event in the second term of \eqref{eq:err_div_linear} can be written with $\mathcal{C}$. We then have
    \begin{align}
        & \sum_{t=1}^{T}\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) = \underline{W}(1))\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \notag\\
        = & \sum_{t=1}^{T}p_{t}\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \\
        = & \sum_{t=1}^{T}p_{t}\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t')) \oplus\theta(\underline{Y})\oplus \pi(\underline{e}(t)) \in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \\
        = & \sum_{t=1}^{T}p_{t}\Pr(\pi(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)), \end{align}
    where the transition from~\eqref{eq:Long5.1} to~\eqref{eq:Long5.2} follows from the fact that $\mathcal{C}$ forms a vector space over $\mathbb{F}_2$ and is closed under modulo-two addition. In particular, under the condition $\theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)\in \mathcal{C}$, we have
    \begin{equation}
    \theta(\underline{Y})\oplus \pi(\underline{e}(t')) \in \mathcal{C}
    \;\Longleftrightarrow\;
    \pi(\underline{e}(t')) \oplus \pi(\underline{e}(t)) \in \mathcal{C},
    \end{equation}
    which leads to~\eqref{eq:Long5.2}.

    In summary,~\eqref{eq:err_linear} is obtained by decomposing the overall decoding error into two parts according to Proposition~\ref{prop:error_division}. Specifically, the target-miss and target-preemption errors are analyzed using Proposition~\ref{prop:search_problem} and the above derivations, respectively, thereby yielding the following unified expression:
    \begin{align}
        P_{\text{err}} & = \underbrace{1 - \sum_{t=1}^{T}p_t}_{\text{target-miss error}} +  \underbrace{\sum_{t=1}^{T}p_{t}\Pr(\pi(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1))}_{\text{target-preemption error}} 
    \end{align}


    For an output-symmetric channel and the rank-based random permutation $\pi_{\underline{Y}}$, we show that
    \begin{equation}
        \Pr(\pi_{\underline{Y}}(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\, t'< t \mid \theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1)) = \Pr(\pi_{\underline{Y}}(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\, t'< t).
    \end{equation}
    The key observation is that, under an output-symmetric channel, the distribution of $\pi_{\underline{Y}}$ depends only on the order statistics of $|\ell_i|$ and is invariant under permutations of the channel outputs. As a result, $\pi_{\underline{Y}}$ is independent of the event $\theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1)$.

    To formally establish this, consider any fixed coordinate permutation $\sigma$ with $\Pr(\pi_{\underline{Y}}=\sigma)=1/N!$. By Bayes' rule,
    \begin{equation} \Pr(\pi_{\underline{Y}} = \sigma \mid \theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1)) = \frac{ \Pr(\pi_{\underline{Y}} = \sigma) \Pr(\theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1) \mid \pi_{\underline{Y}} = \sigma)}{\Pr(\theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1))}.
    \end{equation}
    By Corollary~\ref{coro:distribution_pt}, the denominator in \eqref{eq:pt_with_pi_0} equals $p_t$, and for the numerator, following Propositions~\ref{prop:search_problem} and~\ref{prop:agp_pi}, we have:
    \begin{align}
        & \Pr(\pi_{\underline{Y}} = \sigma) \Pr(\theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1) \mid \pi_{\underline{Y}} = \sigma) \notag \\
        =  & \int_{\mathbb{R}^N}p_{\underline{Y}}(\underline{y})\left(\prod_{i:e_{r_i} = 1 } \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_{r_i} = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right)\mathbf{1}(\pi_{\underline{y}}= \sigma)\mathrm{d}\underline{y} \end{align}

    In~\eqref{eq:pt_with_pi_1}, consider any $\underline{y}$ and all $N!$ permutations $\tilde{\underline{y}}$ obtained by shuffling its elements. The corresponding $\tilde{\underline{r}}$ and $\tilde{\underline{\ell}}$ satisfy $p_{\underline{Y}}(\underline{y}) = p_{\underline{Y}}(\tilde{\underline{y}})$, and
    \begin{equation}
