We prove the theorem by a pairwise exchange argument. In the same ORB-type GRAND setting as above, only finitely many orderings of the fixed candidate EP set are possible, so $P_{\mathrm{succ}}$ attains its maximum over this finite set; let $\mathcal{E}$ be any ordering that achieves this maximum. If $\{p_t\}$ is not non-increasing, then there exists at least one adjacent pair $(t^{*}, t^{*}+1)$ such that
\begin{equation} p_{t^{*}} < p_{t^{*}+1}.
\end{equation}
Exchange these two EPs and denote the resulting ordered set by $\mathcal{E}'$, where $\underline{e}'(i)=\underline{e}(i)$ for $i\neq t^{*},t^{*}+1$, $\underline{e}'(t^{*})=\underline{e}(t^{*}+1)$, and $\underline{e}'(t^{*}+1)=\underline{e}(t^{*})$. Correspondingly, let $p'_i=p_i$ for $i\neq t^{*},t^{*}+1$, $p'_{t^{*}}=p_{t^{*}+1}$, and $p'_{t^{*}+1}=p_{t^{*}}$. The decoding success probabilities before and after the exchange are, respectively,
    \begin{gather}
    P_{\mathrm{succ}}=\sum_{t=1}^{T}p_t-\sum_{t=1}^{T}p_tf(\mathcal{C},\mathcal{E},t),\\
    P_{\mathrm{succ}}'=\sum_{t=1}^{T}p'_t-\sum_{t=1}^{T}p'_tf(\mathcal{C},\mathcal{E}',t).
\end{gather}
We next prove that $P_{\mathrm{succ}}'\ge P_{\mathrm{succ}}$, equivalently that $P_{\mathrm{succ}}'-P_{\mathrm{succ}}\ge 0$. We expand this difference, express the relevant $f(\cdot)$ terms using auxiliary events, and show that the resulting expression is nonnegative under \eqref{eq:th_7_prove_0}. Writing out the difference, we obtain
\begin{align}
    P_{\mathrm{succ}}' - P_{\mathrm{succ}} ={}& \sum_{t=1}^{T}p'_t - \sum_{t=1}^{T}p'_t f(\mathcal{C},\mathcal{E}',t) - \sum_{t=1}^{T}p_t + \sum_{t=1}^{T}p_tf(\mathcal{C},\mathcal{E},t) \notag \\
    ={}& p_{t^{*}}f(\mathcal{C},\mathcal{E},t^{*}) + p_{t^{*}+1}f(\mathcal{C},\mathcal{E},t^{*}+1) - p'_{t^{*}}f(\mathcal{C},\mathcal{E}',t^{*}) - p'_{t^{*}+1}f(\mathcal{C},\mathcal{E}',t^{*}+1) \\
    ={}& p_{t^{*}}f(\mathcal{C},\mathcal{E},t^{*}) + p_{t^{*}+1}f(\mathcal{C},\mathcal{E},t^{*}+1) - p_{t^{*}+1}f(\mathcal{C},\mathcal{E}',t^{*}) - p_{t^{*}}f(\mathcal{C},\mathcal{E}',t^{*}+1) \notag \\
    ={}& p_{t^{*}+1}(f(\mathcal{C},\mathcal{E},t^{*}+1) - f(\mathcal{C},\mathcal{E}',t^{*})) - p_{t^{*}}(f(\mathcal{C},\mathcal{E}',t^{*}+1) - f(\mathcal{C},\mathcal{E},t^{*})). \end{align}

Define the events
\begin{equation}
B \triangleq \{\pi(\underline{e}(t^{*})\oplus \underline{e}(t^{*}+1))\in\mathcal{C}\},
\end{equation}
\begin{equation}
A_1 \triangleq \{\pi(\underline{e}(t')\oplus \underline{e}(t^{*}))\in\mathcal{C},\ \exists\, t'<t^{*}\},\quad
A_2 \triangleq \{\pi(\underline{e}(t')\oplus \underline{e}(t^{*}+1))\in\mathcal{C},\ \exists\, t'<t^{*}\}.
\end{equation}
As illustrated in Fig.~\ref{fig:linear_pairwise_exchange}, $A_1$ and $A_2$ describe the prefix-related codeword-hit events associated with $\underline{e}(t^{*})$ and $\underline{e}(t^{*}+1)$, respectively, whereas $B$ describes the codeword-hit event induced by the adjacent pair. Hence the adjacent-pair contribution is attached to the later EP in the current ordering: before the exchange it appears in the term for $\underline{e}(t^{*}+1)$, while after the exchange it appears in the term for $\underline{e}(t^{*})$.
Then, by construction,
\begin{align}
    f(\mathcal{C},\mathcal{E},t^{*}) &= \Pr(A_1),\ f(\mathcal{C},\mathcal{E},t^{*}+1) = \Pr(A_2 \cup B), \\
    f(\mathcal{C},\mathcal{E}',t^{*}) &= \Pr(A_2),\ f(\mathcal{C},\mathcal{E}',t^{*}+1) = \Pr(A_1 \cup B).
\end{align}

Therefore, we have
\begin{align}
    f(\mathcal{C},\mathcal{E},t^{*}+1)-f(\mathcal{C},\mathcal{E}',t^{*})
    &= \Pr(A_2\cup B)-\Pr(A_2) = \Pr(B\cap A_2^c), \\
    f(\mathcal{C},\mathcal{E}',t^{*}+1)-f(\mathcal{C},\mathcal{E},t^{*})
    &= \Pr(A_1\cup B)-\Pr(A_1) = \Pr(B\cap A_1^c). \end{align}

