\mathbf{H}_j(\underline{0},\cdot).
\end{equation}
For any $\underline{b}\neq\underline{0}$,
\begin{equation}
\mathbf{B}_j(\underline{b},\cdot)
=
\frac{1}{2}\left(
\mathbf{H}_j(\underline{0},\cdot)
-
\mathbf{H}_j(\underline{b},\cdot)
\right),
\end{equation}
because the right-hand side equals $0$ when $\underline{b}\cdot\underline{s}=0$ and equals $1$ when $\underline{b}\cdot\underline{s}=1$.

Suppose that a linear combination of the rows of $\mathbf{B}_j$ is zero:
