Therefore, under the condition that the codeword tester stops after the $t$-th test, the probability of decoding correctly is:
    \begin{align}
        \frac{\Pr(\text{correct at }t)}{P_{\text{stop}}(t)} & = \frac{p_t(1-f(t))}{p_t(1-f(t)) + (1 - \sum_{i=1}^{t}p_i)(f(t+1)-f(t))} \\

        & = \frac{p_t}{p_t + (1 - \sum_{i=1}^{t}p_i)\left(1 - \frac{1 - f(t+1)}{1 - f(t)}\right)} = \frac{p_t}{p_t + (1 - \sum_{i=1}^{t}p_i)\left( \frac{2^K-1}{2^N-t}\right)},
    \end{align}
    for $t = 1, \ldots, T - 1$, and
    \begin{equation}
        \frac{\Pr(\text{correct at }T)}{P_{\text{stop}}(T)} = \frac{p_T(1-f(T))}{(1-\sum_{i=1}^{T-1}p_i)(1 - f(T))} = \frac{p_T}{1 - \sum_{i=1}^{T-1}p_i},
    \end{equation}
    for stopping after $T$ tests.

Therefore, in order to maximize $P_{\text{succ}}$, the tested EPs should be selected and ordered according to:
     \begin{equation} p_1\geq p_2\geq \cdots\geq p_T, \text{ and }\ p_i\geq p_j,\ \forall\ i\leq T<j.
     \end{equation}

Meanwhile, Theorem~\ref{th:ave_guess_num} gives the average number of tests as
     \begin{equation}
         Q = T- \sum_{t=1}^{T} f(t) - \sum_{t=1}^{T-1}p_t\left(T -t - \sum_{i=t+1} ^{T}f(i)\right),
     \end{equation}
     notice that $\left(T -t - \sum_{i=t+1}^{T}f(i)\right)$ decreases monotonically with $t$ since any $f(i)$ is less than 1.

Based on the randomized indexing introduced in Section~\ref{SubSec:linear_channel_model} and the reasoning of Proposition~\ref{prop:error_division}, the total decoding error probability can be expressed as
    \begin{align}
        P_{\text{err}} & = \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t))\neq \underline{W}(1),\forall\ t\leq  T) \notag\\
        & \quad \quad + \sum_{t=1}^{T}\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) = \underline{W}(1)) \notag\\
        & \quad \quad \cdot\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathbfcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)). \end{align}
    The first term represents the event that the target EP $\theta(\underline{Y}) \oplus \underline{W}(1)$ is not contained in the tested EP set $\pi(\mathcal{E})$ (target-miss error), whereas the second term corresponds to the event that $\theta(\underline{Y}) \oplus \underline{W}(1)\in\pi(\mathcal{E})$ but at least another codeword in $\mathcal{C}$ also satisfies the verification condition before the target is reached (target-preemption error).

We next consider the target-preemption error. Since $\mathbfcal{C}$ is only a randomized indexing of the fixed codebook $\mathcal{C}$, the codeword-membership event in the second term of \eqref{eq:err_div_linear} can be written with $\mathcal{C}$. We then have
    \begin{align}
        & \sum_{t=1}^{T}\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) = \underline{W}(1))\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \notag\\
        = & \sum_{t=1}^{T}p_{t}\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t'))\in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \\
        = & \sum_{t=1}^{T}p_{t}\Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t')) \oplus\theta(\underline{Y})\oplus \pi(\underline{e}(t)) \in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)) \\
        = & \sum_{t=1}^{T}p_{t}\Pr(\pi(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)), \end{align}
    where the transition from~\eqref{eq:Long5.1} to~\eqref{eq:Long5.2} follows from the fact that $\mathcal{C}$ forms a vector space over $\mathbb{F}_2$ and is closed under modulo-two addition. In particular, under the condition $\theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1)\in \mathcal{C}$, we have
    \begin{equation}
    \theta(\underline{Y})\oplus \pi(\underline{e}(t')) \in \mathcal{C}
    \;\Longleftrightarrow\;
    \pi(\underline{e}(t')) \oplus \pi(\underline{e}(t)) \in \mathcal{C},
    \end{equation}
    which leads to~\eqref{eq:Long5.2}.

In summary,~\eqref{eq:err_linear} is obtained by decomposing the overall decoding error into two parts according to Proposition~\ref{prop:error_division}. Specifically, the target-miss and target-preemption errors are analyzed using Proposition~\ref{prop:search_problem} and the above derivations, respectively, thereby yielding the following unified expression:
    \begin{align}
        P_{\text{err}} & = \underbrace{1 - \sum_{t=1}^{T}p_t}_{\text{target-miss error}} +  \underbrace{\sum_{t=1}^{T}p_{t}\Pr(\pi(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\ t'< t \mid \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1))}_{\text{target-preemption error}} 
    \end{align}

For an output-symmetric channel and the rank-based random permutation $\pi_{\underline{Y}}$, we show that
    \begin{equation}
        \Pr(\pi_{\underline{Y}}(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\, t'< t \mid \theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1)) = \Pr(\pi_{\underline{Y}}(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\, t'< t).
    \end{equation}
    The key observation is that, under an output-symmetric channel, the distribution of $\pi_{\underline{Y}}$ depends only on the order statistics of $|\ell_i|$ and is invariant under permutations of the channel outputs. As a result, $\pi_{\underline{Y}}$ is independent of the event $\theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1)$.

For an output-symmetric channel and the rank-based random permutation $\pi_{\underline{Y}}$, we show that
    \begin{equation}
        \Pr(\pi_{\underline{Y}}(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\, t'< t \mid \theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1)) = \Pr(\pi_{\underline{Y}}(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\, t'< t).
    \end{equation}

To formally establish this, consider any fixed coordinate permutation $\sigma$ with $\Pr(\pi_{\underline{Y}}=\sigma)=1/N!$. By Bayes' rule,
    \begin{equation} \Pr(\pi_{\underline{Y}} = \sigma \mid \theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1)) = \frac{ \Pr(\pi_{\underline{Y}} = \sigma) \Pr(\theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1) \mid \pi_{\underline{Y}} = \sigma)}{\Pr(\theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1))}.
    \end{equation}

By Corollary~\ref{coro:distribution_pt}, the denominator in \eqref{eq:pt_with_pi_0} equals $p_t$, and for the numerator, following Propositions~\ref{prop:search_problem} and~\ref{prop:agp_pi}, we have:
    \begin{align}
        & \Pr(\pi_{\underline{Y}} = \sigma) \Pr(\theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1) \mid \pi_{\underline{Y}} = \sigma) \notag \\
        =  & \int_{\mathbb{R}^N}p_{\underline{Y}}(\underline{y})\left(\prod_{i:e_{r_i} = 1 } \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_{r_i} = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right)\mathbf{1}(\pi_{\underline{y}}= \sigma)\mathrm{d}\underline{y} \end{align}

In~\eqref{eq:pt_with_pi_1}, consider any $\underline{y}$ and all $N!$ permutations $\tilde{\underline{y}}$ obtained by shuffling its elements. The corresponding $\tilde{\underline{r}}$ and $\tilde{\underline{\ell}}$ satisfy $p_{\underline{Y}}(\underline{y}) = p_{\underline{Y}}(\tilde{\underline{y}})$, and
    \begin{equation}
        \prod_{i:e_{r_i} = 1 } \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_{r_i} = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)} = \prod_{i:e_{\Tilde{r}_i} = 1 } \frac{1}{1+\exp(|\Tilde{\ell}_i|)} \prod_{i:e_{\Tilde{r}_i} = 0} \frac{\exp(|\Tilde{\ell}_i|)} {1+\exp(|\Tilde{\ell}_i|)}.
    \end{equation}
    That is, these $N!$ terms have identical values, but only one of the permutations $\tilde{\underline{y}}$ yields $\pi_{\tilde{\underline{y}}} = \sigma$. Hence,
    \begin{equation} \eqref{eq:pt_with_pi_1} = \frac{1}{N!}\int_{\mathbb{R}^N}p_{\underline{Y}}(\underline{y})\left(\prod_{i:e_{r_i} = 1 } \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_{r_i} = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right)\mathrm{d}\underline{y} = \frac{p_t}{N!}
    \end{equation}

Substituting~\eqref{eq:pt_with_pi_2} into~\eqref{eq:pt_with_pi_0} gives $\Pr(\pi_{\underline{Y}} = \sigma \mid \theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1)) = \frac{1}{N!}= \Pr(\pi_{\underline{Y}} = \sigma)$; that is, $\pi_{\underline{Y}}$ and the event $\theta(\underline{Y})\oplus \pi_{\underline{Y}}(\underline{e}(t))=\underline{W}(1)$ are independent. So we have:
    \begin{equation}
        \eqref{eq:Long5.3} = \sum_{t=1}^{T}p_{t}\Pr(\pi_{\underline{Y}}(\underline{e}(t') \oplus \underline{e}(t)) \in \mathcal{C},\exists\ t'< t). \end{equation}

If $\{p_t\}$ is not non-increasing, then there exists at least one adjacent pair $(t^{*}, t^{*}+1)$ such that
\begin{equation} p_{t^{*}} < p_{t^{*}+1}.
\end{equation}

Exchange these two EPs and denote the resulting ordered set by $\mathcal{E}'$, where $\underline{e}'(i)=\underline{e}(i)$ for $i\neq t^{*},t^{*}+1$, $\underline{e}'(t^{*})=\underline{e}(t^{*}+1)$, and $\underline{e}'(t^{*}+1)=\underline{e}(t^{*})$. Correspondingly, let $p'_i=p_i$ for $i\neq t^{*},t^{*}+1$, $p'_{t^{*}}=p_{t^{*}+1}$, and $p'_{t^{*}+1}=p_{t^{*}}$. The decoding success probabilities before and after the exchange are, respectively,
    \begin{gather}
    P_{\mathrm{succ}}=\sum_{t=1}^{T}p_t-\sum_{t=1}^{T}p_tf(\mathcal{C},\mathcal{E},t),\\
    P_{\mathrm{succ}}'=\sum_{t=1}^{T}p'_t-\sum_{t=1}^{T}p'_tf(\mathcal{C},\mathcal{E}',t).
\end{gather}

We next prove that $P_{\mathrm{succ}}'\ge P_{\mathrm{succ}}$, equivalently that $P_{\mathrm{succ}}'-P_{\mathrm{succ}}\ge 0$. We expand this difference, express the relevant $f(\cdot)$ terms using auxiliary events, and show that the resulting expression is nonnegative under \eqref{eq:th_7_prove_0}. Writing out the difference, we obtain
\begin{align}
    P_{\mathrm{succ}}' - P_{\mathrm{succ}} ={}& \sum_{t=1}^{T}p'_t - \sum_{t=1}^{T}p'_t f(\mathcal{C},\mathcal{E}',t) - \sum_{t=1}^{T}p_t + \sum_{t=1}^{T}p_tf(\mathcal{C},\mathcal{E},t) \notag \\
    ={}& p_{t^{*}}f(\mathcal{C},\mathcal{E},t^{*}) + p_{t^{*}+1}f(\mathcal{C},\mathcal{E},t^{*}+1) - p'_{t^{*}}f(\mathcal{C},\mathcal{E}',t^{*}) - p'_{t^{*}+1}f(\mathcal{C},\mathcal{E}',t^{*}+1) \\
    ={}& p_{t^{*}}f(\mathcal{C},\mathcal{E},t^{*}) + p_{t^{*}+1}f(\mathcal{C},\mathcal{E},t^{*}+1) - p_{t^{*}+1}f(\mathcal{C},\mathcal{E}',t^{*}) - p_{t^{*}}f(\mathcal{C},\mathcal{E}',t^{*}+1) \notag \\
    ={}& p_{t^{*}+1}(f(\mathcal{C},\mathcal{E},t^{*}+1) - f(\mathcal{C},\mathcal{E}',t^{*})) - p_{t^{*}}(f(\mathcal{C},\mathcal{E}',t^{*}+1) - f(\mathcal{C},\mathcal{E},t^{*})). \end{align}

Define the events
\begin{equation}
B \triangleq \{\pi(\underline{e}(t^{*})\oplus \underline{e}(t^{*}+1))\in\mathcal{C}\},
\end{equation}
\begin{equation}
A_1 \triangleq \{\pi(\underline{e}(t')\oplus \underline{e}(t^{*}))\in\mathcal{C},\ \exists\, t'<t^{*}\},\quad
A_2 \triangleq \{\pi(\underline{e}(t')\oplus \underline{e}(t^{*}+1))\in\mathcal{C},\ \exists\, t'<t^{*}\}.
\end{equation}
As illustrated in Fig.~\ref{fig:linear_pairwise_exchange}, $A_1$ and $A_2$ describe the prefix-related codeword-hit events associated with $\underline{e}(t^{*})$ and $\underline{e}(t^{*}+1)$, respectively, whereas $B$ describes the codeword-hit event induced by the adjacent pair. Hence the adjacent-pair contribution is attached to the later EP in the current ordering: before the exchange it appears in the term for $\underline{e}(t^{*}+1)$, while after the exchange it appears in the term for $\underline{e}(t^{*})$.
Then, by construction,
\begin{align}
    f(\mathcal{C},\mathcal{E},t^{*}) &= \Pr(A_1),\ f(\mathcal{C},\mathcal{E},t^{*}+1) = \Pr(A_2 \cup B), \\
    f(\mathcal{C},\mathcal{E}',t^{*}) &= \Pr(A_2),\ f(\mathcal{C},\mathcal{E}',t^{*}+1) = \Pr(A_1 \cup B).
\end{align}

Therefore, we have
\begin{align}
    f(\mathcal{C},\mathcal{E},t^{*}+1)-f(\mathcal{C},\mathcal{E}',t^{*})
    &= \Pr(A_2\cup B)-\Pr(A_2) = \Pr(B\cap A_2^c), \\
    f(\mathcal{C},\mathcal{E}',t^{*}+1)-f(\mathcal{C},\mathcal{E},t^{*})
    &= \Pr(A_1\cup B)-\Pr(A_1) = \Pr(B\cap A_1^c). \end{align}

We now show that
\begin{equation} B\cap A_1^c = B\cap A_2^c,
\end{equation}
so as to prove $\eqref{eq:th_7_clean_2} = \eqref{eq:th_7_clean_3}$. Under the event $B$, we have
\begin{equation}
\pi(\underline{e}(t^{*})\oplus \underline{e}(t^{*}+1))\in\mathcal{C}.
\end{equation}
For any $t'<t^{*}$,
\begin{equation}
\pi(\underline{e}(t')\oplus \underline{e}(t^{*}))
= \pi(\underline{e}(t')\oplus \underline{e}(t^{*}+1)) \oplus \pi(\underline{e}(t^{*}+1)\oplus \underline{e}(t^{*})).
\end{equation}
Since $\mathcal{C}$ is linear, the modulo-two sum of a codeword and a non-codeword is a non-codeword. Hence, under $B$, the condition
\begin{equation}
\pi(\underline{e}(t')\oplus \underline{e}(t^{*}+1))\notin\mathcal{C},\ \forall\, t'<t^{*}
\end{equation}
holds if and only if
\begin{equation}
\pi(\underline{e}(t')\oplus \underline{e}(t^{*}))\notin\mathcal{C},\ \forall\, t'<t^{*}.
\end{equation}
This proves \eqref{eq:th_7_clean_4}, and therefore
\begin{equation}
    \Pr(B\cap A_1^c)=\Pr(B\cap A_2^c).
\end{equation}

Under the event $B$, we have
\begin{equation}
\pi(\underline{e}(t^{*})\oplus \underline{e}(t^{*}+1))\in\mathcal{C}.
\end{equation}

For any $t'<t^{*}$,
\begin{equation}
\pi(\underline{e}(t')\oplus \underline{e}(t^{*}))
= \pi(\underline{e}(t')\oplus \underline{e}(t^{*}+1)) \oplus \pi(\underline{e}(t^{*}+1)\oplus \underline{e}(t^{*})).
\end{equation}

Since $\mathcal{C}$ is linear, the modulo-two sum of a codeword and a non-codeword is a non-codeword. Hence, under $B$, the condition
\begin{equation}
\pi(\underline{e}(t')\oplus \underline{e}(t^{*}+1))\notin\mathcal{C},\ \forall\, t'<t^{*}
\end{equation}
holds if and only if
\begin{equation}
\pi(\underline{e}(t')\oplus \underline{e}(t^{*}))\notin\mathcal{C},\ \forall\, t'<t^{*}.
\end{equation}

This proves \eqref{eq:th_7_clean_4}, and therefore
\begin{equation}
    \Pr(B\cap A_1^c)=\Pr(B\cap A_2^c).
\end{equation}

Substituting \eqref{eq:th_7_clean_2} and \eqref{eq:th_7_clean_3} into \eqref{eq:th_7_prove_2}, we obtain
\begin{align}
    P_{\mathrm{succ}}'-P_{\mathrm{succ}}
    &= p_{t^{*}+1}\Pr(B\cap A_2^c)-p_{t^{*}}\Pr(B\cap A_1^c) = \Pr(B\cap A_1^c)\left(p_{t^{*}+1}-p_{t^{*}}\right)\overset{(a)}{\geq}0, \end{align}
where $(a)$ follows from \eqref{eq:th_7_prove_0}. Hence, whenever an adjacent pair satisfies $p_{t^{*}}<p_{t^{*}+1}$, exchanging these two EPs cannot decrease $P_{\mathrm{succ}}$. The same reasoning applies to any index pair $(t,t+1)$ with $p_t<p_{t+1}$: the corresponding adjacent exchange does not decrease $P_{\mathrm{succ}}$.

Therefore, starting from any ordering of the fixed candidate EP set, we may repeatedly apply such adjacent exchanges (whenever some adjacent pair violates $p_t\ge p_{t+1}$) until the associated $\{p_t\}_{t=1}^{T}$ is non-increasing, and the decoding success probability never decreases along this process. In particular, let $\mathcal{E}$ maximize $P_{\mathrm{succ}}$ over all orderings of this candidate set, which exists because only finitely many such orderings exist. Performing the above exchanges from $\mathcal{E}$ preserves the value of $P_{\mathrm{succ}}$ at its global maximum, and after finitely many steps we obtain an ordering whose associated $\{p_t\}_{t=1}^{T}$ satisfies
\begin{equation}
p_1 \ge p_2 \ge \cdots \ge p_T.
\end{equation}
This exhibits an ordering of the fixed candidate EP set that maximizes the decoding success probability and whose associated sequence $\{p_t\}_{t=1}^{T}$ is non-increasing, as stated in the theorem.

By definition, $\Pr\!\left(\bigcap_{k=1}^{j}A_{i_k t}\right)=\Pr\!\left(\bigcap_{k=1}^{j}\{\pi(\underline{e}(i_k,t))\in\mathcal{C}\}\right).$ Partition the event on the right-hand side according to the ordered codeword tuple $[\underline{u}(1),\ldots,\underline{u}(j)]\in\mathcal{C}^j$ satisfying $\pi(\underline{e}(i_k,t))=\underline{u}(k)$ for all $k$. Then
\begin{equation}
\Pr\!\left(\bigcap_{k=1}^{j}A_{i_k t}\right)
=
\sum_{[\underline{u}(1),\ldots,\underline{u}(j)]\in\mathcal{C}^j}
\Pr\!\left(\bigcap_{k=1}^{j}\{\pi(\underline{e}(i_k,t))=\underline{u}(k)\}\right). \end{equation}

This correspondence can be visualized by arranging the vectors into a matrix form, where each column represents a coordinate and its associated state:
\begin{align}
    &\left[\begin{array}[pos]{cccc}
        x_1(1) & x_2(1) & \cdots & x_N(1)\\
        x_1(2) & x_2(2) & \cdots & x_N(2)\\
        \vdots & \vdots & \ddots & \vdots\\
        x_1(j) & x_2(j) & \cdots & x_N(j)
    \end{array}\right]
    \overset{\sigma}{\longrightarrow}
    \left[\begin{array}[pos]{cccc}
        \sigma(\underline{x}(1))_1 & \sigma(\underline{x}(1))_2 & \cdots & \sigma(\underline{x}(1))_N\\
        \sigma(\underline{x}(2))_1 & \sigma(\underline{x}(2))_2 & \cdots & \sigma(\underline{x}(2))_N\\
        \vdots & \vdots & \ddots & \vdots\\
        \sigma(\underline{x}(j))_1 & \sigma(\underline{x}(j))_2 & \cdots & \sigma(\underline{x}(j))_N
    \end{array}\right], \end{align}
where each column is a state vector and must be mapped to a column with the same state in the target tuple.

By Proposition~\ref{prop:rearrange_number}, for every ordered codeword tuple appearing in this summation, the number of admissible coordinate permutations depends only on the common weight relationship $\mathbf{g}=\mathcal{F}(\underline{e}(i_1,t),\ldots,\underline{e}(i_j,t))$ and is given by $\mathcal{H}(\mathbf{g})$ in \eqref{eq:H_by_J}. Hence,
\begin{equation}
\Pr\!\left(
\bigcap_{k=1}^{j}\{\pi(\underline{e}(i_k,t))=\underline{u}(k)\}
\right)
=
\frac{1}{N!}\mathcal{H}(\mathbf{g}).
\end{equation}

Applying Theorem~\ref{th:linear_pre_target_hit} with $j=1$, we have
\begin{align}
\Pr(A_{it}) = \frac{1}{N!}Z(\mathbf{g}_{it}^{(1)})\mathcal{H}(\mathbf{g}_{it}^{(1)}).
\end{align}

To compute $\mathcal{H}(\mathbf{g}_{it}^{(1)})$, note that for $j=1$,
\begin{equation}
\left[\begin{array}{c}
J(0) \\ J(1)
\end{array}\right]
=
\left[\begin{array}{cc}
1 & 1 \\
0 & 1
\end{array}\right]^{-1}
\left[\begin{array}{c}
N \\ w_{\mathrm{H}}(\underline{e}(i,t))
\end{array}\right]
=
\left[\begin{array}{c}
N-w_{\mathrm{H}}(\underline{e}(i,t)) \\ w_{\mathrm{H}}(\underline{e}(i,t))
\end{array}\right].
\end{equation}

Hence $\mathcal{H}(\mathbf{g}_{it}^{(1)})=\bigl(N-w_{\mathrm{H}}(\underline{e}(i,t))\bigr)!w_{\mathrm{H}}(\underline{e}(i,t))!$, which gives
\begin{equation}
\Pr(A_{it}) = \frac{Z(\mathbf{g}_{it}^{(1)})}{C_{N}^{w_{\mathrm{H}}(\underline{e}(i,t))}}.
\end{equation}

If $b_1=0$, then $\underline{b}=\underline{0}$ holds if and only if $\tilde{\underline{b}}=\underline{0}$, and for $\underline{b}\neq \underline{0}$ we have
\begin{equation}
\underline{b}\cdot\underline{s}
=
\tilde{\underline{b}}\cdot\tilde{\underline{s}}.
\end{equation}
Therefore, both the upper-left block $(b_1,s_1)=(0,0)$ and the upper-right block $(b_1,s_1)=(0,1)$ are equal to $\mathbf{B}_j$.

Now consider $b_1=1$. Then $\underline{b}\neq \underline{0}$ always holds. If $s_1=0$, then
\begin{equation}
\underline{b}\cdot\underline{s}
=
\tilde{\underline{b}}\cdot\tilde{\underline{s}}.
\end{equation}
Hence the lower-left block agrees with $\mathbf{B}_j$ for all rows except the first row, corresponding to $\tilde{\underline{b}}=\underline{0}$. In that row, the entries of $\mathbf{B}_j$ are all $1$, whereas the entries of the lower-left block are all $0$. Therefore, the lower-left block is
\begin{equation}
\mathbf{E}^{2^j\times 2^j}_{1,1:2^j}\oplus \mathbf{B}_j.
\end{equation}

If $s_1=1$, then
\begin{equation}
\underline{b}\cdot\underline{s}
=
1\oplus \tilde{\underline{b}}\cdot\tilde{\underline{s}}.
\end{equation}
Thus, for all rows except the first row, the lower-right block is obtained from $\mathbf{B}_j$ by flipping all bits, namely by $\mathbf{1}^{2^j\times 2^j}\oplus \mathbf{B}_j$. For the first row corresponding to $\tilde{\underline{b}}=\underline{0}$, the entries should all be $1$, so an additional flip of the first row is needed. Hence the lower-right block is
\begin{equation}
\mathbf{E}^{2^j\times 2^j}_{1,1:2^j}\oplus \mathbf{1}^{2^j\times 2^j}\oplus \mathbf{B}_j.
\end{equation}

Combining the four blocks gives
\begin{equation}
\mathbf{B}_{j+1}
=
\begin{bmatrix}
\mathbf{B}_j & \mathbf{B}_j\\
\mathbf{E}_{1,1:2^j}^{2^j\times 2^j}\oplus \mathbf{B}_j &
\mathbf{E}_{1,1:2^j}^{2^j\times 2^j}\oplus \mathbf{1}^{2^j\times 2^j}\oplus \mathbf{B}_j
\end{bmatrix},
\end{equation}
which proves \eqref{eq:Bj_recursion_new}.

Consider the sign matrix $\mathbf{H}_j$ indexed by $\{0,1\}^j\times\{0,1\}^j$, with entries
\begin{equation}
\bigl[\mathbf{H}_j\bigr]_{\underline{b},\underline{s}}
=
(-1)^{\underline{b}\cdot\underline{s}},
\qquad
\underline{b},\underline{s}\in\{0,1\}^j .
\end{equation}

The rows of $\mathbf{H}_j$ are orthogonal, since
\begin{equation}
\sum_{\underline{s}\in\{0,1\}^j}
(-1)^{(\underline{b}\oplus\underline{b}')\cdot\underline{s}}
=
\begin{cases}
2^j, & \underline{b}=\underline{b}',\\
0, & \underline{b}\neq \underline{b}'.
\end{cases}
\end{equation}
Indeed, when $\underline{b}\neq \underline{b}'$, the nonzero linear form $(\underline{b}\oplus\underline{b}')\cdot\underline{s}$ takes the values $0$ and $1$ equally often as $\underline{s}$ ranges over $\{0,1\}^j$, so the corresponding signs cancel.
Thus $\mathbf{H}_j\mathbf{H}_j^{\mathsf T}=2^j\mathbf{I}$, and $\mathbf{H}_j$ is nonsingular.

Suppose that a linear combination of the rows of $\mathbf{B}_j$ is zero:
\begin{equation}
a_{\underline{0}}\mathbf{B}_j(\underline{0},\cdot)
+
\sum_{\underline{b}\neq\underline{0}}
a_{\underline{b}}\mathbf{B}_j(\underline{b},\cdot)
=
\mathbf{0}.
\end{equation}

Substituting the row relations above gives
\begin{equation}
\left(
a_{\underline{0}}
+
\frac{1}{2}\sum_{\underline{b}\neq\underline{0}}a_{\underline{b}}
\right)
\mathbf{H}_j(\underline{0},\cdot)
-
\frac{1}{2}
\sum_{\underline{b}\neq\underline{0}}
a_{\underline{b}}\mathbf{H}_j(\underline{b},\cdot)
=
\mathbf{0}.
\end{equation}
Since the rows of $\mathbf{H}_j$ are linearly independent, all coefficients in this combination are zero. Hence $a_{\underline{b}}=0$ for every $\underline{b}\neq\underline{0}$, and then $a_{\underline{0}}=0$. Therefore the rows of $\mathbf{B}_j$ are linearly independent, so $\mathbf{B}_j$ is nonsingular over $\mathbb{R}$.
